DECLARE unknown int; moved int;
BEGIN
  SELECT count(*) INTO unknown FROM candidates c WHERE c.election_id IN ('f6a7b8c9-d0e1-2345-f012-567890122011', 'f6a7b8c9-d0e1-2345-f012-567890122016', 'f6a7b8c9-d0e1-2345-f012-567890122021')
    AND NOT EXISTS (SELECT 1 FROM as_old_seed o WHERE o.id = c.id);
  SELECT count(*) INTO moved FROM candidates c JOIN as_old_seed o ON o.id = c.id WHERE c.party_id IS DISTINCT FROM o.party_id;
  IF unknown > 0 OR moved > 0 THEN
    RAISE EXCEPTION 'seed_as_corrections_v1: % Assam candidates are not in the old seeds and % changed party since; reconcile them first (docs/DEPLOYMENT.md 5.0a)', unknown, moved;
  END IF;
END $$;

